package com.taizur.lootlogger;

import java.io.File;
import java.io.IOException;
import net.runelite.client.RuneLite;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.util.ArrayList;
import java.util.Collection;
import lombok.extern.slf4j.Slf4j;
import java.util.List;


@Slf4j
public class CsvDropRepository
{
    private final File pluginDirectory;
    private final File csvFile;

    public CsvDropRepository()
    {
        pluginDirectory = new File(RuneLite.RUNELITE_DIR, "taizurs-loot-logger");
        csvFile = new File(pluginDirectory, "loot-log.csv");
    }

    public void initialize() throws IOException
    {
        if (!pluginDirectory.exists())
        {
            boolean directoryCreated = pluginDirectory.mkdirs();

            if (!directoryCreated)
            {
                throw new IOException("Failed to create plugin directory.");
            }
        }

        if (!csvFile.exists())
        {
            boolean fileCreated = csvFile.createNewFile();

            if (!fileCreated)
            {
                throw new IOException("Failed to create loot log file.");
            }
        }
    }

    public void save(Collection<DropTotal> drops) throws IOException
    {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(csvFile)))
        {
            writer.write("Item ID,Item Name,Tradeable,Total Quantity,GE Price");
            writer.newLine();

            for (DropTotal drop: drops)
            {
                String row =
                        drop.getItemId() + "," +
                                escapeCsv(drop.getItemName()) + "," +
                                drop.isTradeable() + "," +
                                drop.getTotalQuantity() + "," +
                                drop.getGePrice();
                writer.write(row);
                writer.newLine();
            }
        }
    }

    public Collection<DropTotal> load() throws IOException
    {
        Collection<DropTotal> loadedDrops = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(csvFile)))
        {
            String line = reader.readLine(); // skip header

            while ((line = reader.readLine()) != null)
            {
                if (line.isBlank())
                {
                    continue;
                }

                List<String> values = parseCsvLine(line);

                if (values.size() != 5)
                {
                    log.warn("Skipping malformed loot log row: {}", line);
                    continue;
                }

                try
                {
                    int itemId = Integer.parseInt(values.get(0));
                    String itemName = values.get(1);
                    boolean tradeable = Boolean.parseBoolean(values.get(2));
                    long totalQuantity = Long.parseLong(values.get(3));
                    int gePrice = Integer.parseInt(values.get(4));

                    DropTotal drop = new DropTotal(
                            itemId,
                            itemName,
                            tradeable,
                            totalQuantity,
                            gePrice
                    );

                    loadedDrops.add(drop);
                }
                catch (NumberFormatException e)
                {
                    log.warn("Skipping malformed loot log row: {}", line);
                }
            }
        }

        return loadedDrops;
    }

    private String escapeCsv(String value)
    {
        return "\"" + value.replace("\"", "\"\"") + "\"";
    }

    private List<String> parseCsvLine(String line)
    {
        List<String> values = new ArrayList<>();
        StringBuilder currentValue = new StringBuilder();
        boolean insideQuotes = false;

        for (int i = 0; i < line.length(); i++)
        {
            char character = line.charAt(i);

            if (character == '"')
            {
                if (insideQuotes
                        && i + 1 < line.length()
                        && line.charAt(i + 1) == '"')
                {
                    currentValue.append('"');
                    i++;
                }
                else
                {
                    insideQuotes = !insideQuotes;
                }
            }
            else if (character == ',' && !insideQuotes)
            {
                values.add(currentValue.toString());
                currentValue.setLength(0);
            }
            else
            {
                currentValue.append(character);
            }
        }

        values.add(currentValue.toString());
        return values;
    }
}

package com.taizur.lootlogger;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;

public class DropLedger {
    private final Map<Integer, DropTotal> drops;
    @Inject
    private ItemManager itemManager;

    public DropLedger()
    {
        drops = new HashMap<>();
    }

    public void addDrop(int itemId, String itemName, long quantity)
    {
        if (drops.containsKey(itemId))
        {
            drops.get(itemId).addQuantity(quantity);
        }
        else
        {
            addNewDrop(itemId, itemName, quantity);
        }
    }

    private void addNewDrop(int itemId, String itemName, long quantity)
    {
        ItemComposition composition = itemManager.getItemComposition(itemId);
        boolean tradeable = composition.isGeTradeable();

        int gePrice = itemManager.getItemPriceWithSource(itemId, true);

        DropTotal newDrop = new DropTotal(itemId, itemName, tradeable, quantity, gePrice);
        drops.put(itemId, newDrop);
    }

    public DropTotal getDrop(int itemId)
    {
        return drops.get(itemId);
    }

    public void updatePrices()
    {
        for (DropTotal drop: drops.values())
        {
            int newPrice = itemManager.getItemPriceWithSource(drop.getItemId(), true);
            drop.setGePrice(newPrice);
        }
    }

    public Collection<DropTotal> getAllDrops()
    {
        return drops.values();
    }

    public void loadDrops(Collection<DropTotal> loadedDrops)
    {
        for (DropTotal loadedDrop : loadedDrops)
        {
            DropTotal existingDrop = drops.get(loadedDrop.getItemId());

            if (existingDrop == null)
            {
                drops.put(loadedDrop.getItemId(), loadedDrop);
            }
            else
            {
                existingDrop.addQuantity(loadedDrop.getTotalQuantity());
            }
        }
    }

    public Collection<DropTotal> snapshotDrops()
    {
        Collection<DropTotal> snapshot = new ArrayList<>();

        for (DropTotal drop : drops.values())
        {
            snapshot.add(new DropTotal(
                    drop.getItemId(),
                    drop.getItemName(),
                    drop.isTradeable(),
                    drop.getTotalQuantity(),
                    drop.getGePrice()
            ));
        }

        return snapshot;
    }

    public void clear()
    {
        drops.clear();
    }
}

package com.taizur.lootlogger;

import lombok.Getter;
import lombok.Setter;

@Getter
public class DropTotal
{
    private final int itemId;
    private final String itemName;
    private final boolean tradeable;
    private long totalQuantity;

    @Setter
    private int gePrice;

    public DropTotal(int itemId, String itemName, boolean tradeable, long totalQuantity, int gePrice)
    {
        this.itemId = itemId;
        this.itemName = itemName;
        this.tradeable = tradeable;
        this.totalQuantity = totalQuantity;
        this.gePrice = gePrice;
    }

    public void addQuantity(long quantity)
    {
        totalQuantity += quantity;
    }
}

package com.taizur.lootlogger;


import javax.inject.Inject;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import lombok.extern.slf4j.Slf4j;
import java.io.IOException;
import java.util.Collection;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.client.events.ServerNpcLoot;


@PluginDescriptor(
	name = "CSV Lifetime Drop Ledger"
)
@Slf4j
public class TaizursLootLoggerPlugin extends Plugin
{

	@Inject
	private ItemManager itemManager;

	@Inject
	private DropLedger ledger;

	@Inject
	private CsvDropRepository repository;

	@Inject
	private ClientThread clientThread;

	private ExecutorService fileExecutor;

	@Override
	protected void startUp()
	{
		ExecutorService executor = Executors.newSingleThreadExecutor();
		fileExecutor = executor;

		executor.submit(() ->
		{
			try
			{
				repository.initialize();
				Collection<DropTotal> loadedDrops = repository.load();

				clientThread.invoke(() ->
				{
					if (fileExecutor != executor || executor.isShutdown())
					{
						return;
					}

					ledger.loadDrops(loadedDrops);
					ledger.updatePrices();
					Collection<DropTotal> snapshot = ledger.snapshotDrops();

					executor.submit(() ->
					{
						try
						{
							repository.save(snapshot);
						}
						catch (IOException e)
						{
							log.error("Failed to save refreshed loot prices", e);
						}
					});
				});
			}
			catch (IOException e)
			{
				log.error("Failed to load loot data", e);
			}
		});
	}
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot lootEvent)
	{
		for(ItemStack loot: lootEvent.getItems())
		{

			int id = loot.getId();
			long quantity = loot.getQuantity();
			ItemComposition composition = itemManager.getItemComposition(id);
			String name = composition.getName();
			ledger.addDrop(id, name, quantity);
		}
		Collection<DropTotal> snapshot = ledger.snapshotDrops();

		fileExecutor.submit(() ->
		{
			try
			{
				repository.save(snapshot);
			}
			catch (IOException e)
			{
				log.error("Failed to save loot data", e);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		fileExecutor.shutdownNow();
		ledger.clear();
	}


}

